//! Events of the bridge contract (`protocol/bridge-ws.md` §5). `Event` is both what the `NetBackend` emits and
//! what the server sends (serialized with its `type` tag); `HelloEvent` is generated by the server itself.

use super::ids::HexData;
use super::ids::{NodeId, PortRef, RdmUid};
use super::model::{BridgeStatus, FlashJob, NetInterface, NodeState, RdmValue, Tod, UdpState};
use serde::{Deserialize, Serialize};
use std::net::Ipv4Addr;

// ── Payloads ──────────────────────────────────────────────────────────────────────────────────────────────────────

/// A queued RDM message the backend fetched with QUEUED_MESSAGE.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
#[allow(missing_docs)]
pub struct RdmQueued {
    pub node_id: NodeId,
    pub port: PortRef,
    pub uid: RdmUid,
    pub sub_device: u16,
    pub pid: u16,
    pub data: HexData,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub value: Option<RdmValue>,
}

/// Priority of an ArtDiagData message.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
#[allow(missing_docs)]
pub enum DiagPriority {
    Low,
    Medium,
    High,
    Critical,
    Volatile,
}

/// ArtDiagData received from a node.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
#[allow(missing_docs)]
pub struct Diag {
    /// `None` when the sender is not in the node table.
    pub node_id: Option<NodeId>,
    pub ip: Ipv4Addr,
    pub priority: DiagPriority,
    pub logical_port: u8,
    pub text: String,
}

/// Level of a `log` event.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
#[allow(missing_docs)]
pub enum LogLevel {
    Debug,
    Info,
    Warn,
    Error,
}

/// Bridge diagnostics worth showing in the app.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
#[allow(missing_docs)]
pub struct LogEntry {
    pub level: LogLevel,
    pub text: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub node_id: Option<NodeId>,
}

impl LogEntry {
    /// Log entry without a node reference.
    pub fn new(level: LogLevel, text: impl Into<String>) -> Self {
        Self {
            level,
            text: text.into(),
            node_id: None,
        }
    }
}

// ── Event ─────────────────────────────────────────────────────────────────────────────────────────────────────────

/// An event delivered to every handshaken connection. Serializes as `{ "type": "<event>", ...payload }`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(
    tag = "type",
    rename_all = "camelCase",
    rename_all_fields = "camelCase"
)]
pub enum Event {
    /// An interface or the UDP socket state changed.
    BridgeStatus(BridgeStatus),
    /// Node first seen, or any field other than `lastSeen` changed.
    Node {
        /// Full node state.
        node: NodeState,
    },
    /// No reply for 3 consecutive poll cycles; the node and its TODs leave the table.
    NodeGone {
        /// The node that left.
        node_id: NodeId,
        /// Its last reply (ms epoch).
        last_seen: u64,
    },
    /// A completely assembled ArtTodData set.
    Tod(Tod),
    /// A queued message fetched with QUEUED_MESSAGE.
    RdmQueued(RdmQueued),
    /// ArtDiagData received.
    Diag(Diag),
    /// Firmware job progress.
    FlashProgress {
        /// Current job state.
        job: FlashJob,
    },
    /// Bridge diagnostics.
    Log(LogEntry),
}

/// First message of every connection (contract §1 Handshake).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "type", rename = "hello")]
pub struct HelloEvent {
    /// Bridge (pmnet) version.
    pub bridge: String,
    /// Protocol semver.
    pub protocol: String,
    /// Local interfaces.
    pub interfaces: Vec<NetInterface>,
    /// Art-Net socket state.
    pub udp: UdpState,
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::protocol::ids::RdmUid;

    #[test]
    fn event_shapes() {
        let ev = Event::NodeGone {
            node_id: NodeId::from("7FF0:8A1B2C3D"),
            last_seen: 5,
        };
        assert_eq!(
            serde_json::to_string(&ev).unwrap(),
            r#"{"type":"nodeGone","nodeId":"7FF0:8A1B2C3D","lastSeen":5}"#
        );

        let tod = Event::Tod(Tod {
            node_id: NodeId::from("n"),
            port: PortRef::new(1, 0),
            port_address: 1,
            available: true,
            uids: vec![RdmUid::new(0x7FF0, 1)],
        });
        assert_eq!(
            serde_json::to_string(&tod).unwrap(),
            r#"{"type":"tod","nodeId":"n","port":{"bind":1,"index":0},"portAddress":1,"available":true,"uids":["7FF0:00000001"]}"#
        );

        let log = Event::Log(LogEntry::new(LogLevel::Warn, "x"));
        assert_eq!(
            serde_json::to_string(&log).unwrap(),
            r#"{"type":"log","level":"warn","text":"x"}"#
        );
        let back: Event =
            serde_json::from_str(r#"{"type":"log","level":"warn","text":"x"}"#).unwrap();
        assert_eq!(back, log);
    }

    #[test]
    fn hello_shape() {
        let hello = HelloEvent {
            bridge: "0.1.0".into(),
            protocol: "1.0.0".into(),
            interfaces: vec![],
            udp: UdpState {
                bound: true,
                port: 6454,
                error: None,
            },
        };
        assert_eq!(
            serde_json::to_string(&hello).unwrap(),
            r#"{"type":"hello","bridge":"0.1.0","protocol":"1.0.0","interfaces":[],"udp":{"bound":true,"port":6454,"error":null}}"#
        );
    }
}
